def choose_move(observation):
    def clamp1(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def sign(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def as_xy(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for keys in (("x", "y"), ("pos",), ("position",), ("loc",), ("location",)):
                if len(keys) == 2 and keys[0] in obj and keys[1] in obj:
                    return [obj.get(keys[0]), obj.get(keys[1])]
                if len(keys) == 1 and keys[0] in obj:
                    return as_xy(obj.get(keys[0]))
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            a, b = obj[0], obj[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [a, b]
        return None

    def get_agent_pos(obs):
        for key in ("agent", "self", "player", "me", "avatar"):
            v = obs.get(key)
            xy = as_xy(v)
            if xy is not None:
                return xy
        for key in ("agent_pos", "self_pos", "player_pos", "pos", "position"):
            xy = as_xy(obs.get(key))
            if xy is not None:
                return xy
        return [0, 0]

    def iter_points(v):
        pts = []
        if v is None:
            return pts
        if isinstance(v, dict):
            for kk in ("items", "points", "targets", "resources", "enemies", "players", "agents", "cells", "objects"):
                if kk in v:
                    pts.extend(iter_points(v.get(kk)))
            xy = as_xy(v)
            if xy is not None:
                pts.append(xy)
            return pts
        if isinstance(v, (list, tuple)):
            if len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float)):
                pts.append([v[0], v[1]])
                return pts
            for e in v:
                pts.extend(iter_points(e))
        return pts

    def nearest_delta(src, pts):
        best = None
        best_d = None
        sx, sy = src[0], src[1]
        for p in pts:
            dx = p[0] - sx
            dy = p[1] - sy
            d = abs(dx) + abs(dy)
            if best_d is None or d < best_d:
                best_d = d
                best = [dx, dy]
        return best

    def find_grid(obs):
        for key in ("grid", "board", "map", "world", "terrain"):
            g = obs.get(key)
            if isinstance(g, (list, tuple)) and g:
                return g
        return None

    def is_blocked(grid, x, y):
        try:
            if y < 0 or x < 0:
                return True
            row = grid[y]
            cell = row[x]
            if cell in (1, True, "#", "X", "x", "wall", "W"):
                return True
        except Exception:
            return True
        return False

    def legal_dirs(grid, pos):
        dirs = [(1,0), (-1,0), (0,1), (0,-1), (0,0)]
        out = []
        for dx, dy in dirs:
            nx, ny = pos[0] + dx, pos[1] + dy
            if grid is None or not is_blocked(grid, nx, ny):
                out.append((dx, dy))
        return out if out else [(0, 0)]

    def choose_from_options(options, preferred):
        if preferred in options:
            return preferred
        if (sign(preferred[0]), sign(preferred[1])) in options:
            return (sign(preferred[0]), sign(preferred[1]))
        if (sign(preferred[0]), 0) in options:
            return (sign(preferred[0]), 0)
        if (0, sign(preferred[1])) in options:
            return (0, sign(preferred[1]))
        return options[0]

    pos = get_agent_pos(observation)
    grid = find_grid(observation)
    options = legal_dirs(grid, pos)

    # collect candidate targets
    targets = []
    for key in ("resource", "resources", "pickup", "pickups", "goal", "goals", "target", "targets", "enemy", "enemies", "opponents", "players", "agents"):
        targets.extend(iter_points(observation.get(key)))

    # Remove self-like targets if present
    filtered = []
    for t in targets:
        if t[0] == pos[0] and t[1] == pos[1]:
            continue
        filtered.append(t)
    targets = filtered

    # Detect mode heuristically
    mode = observation.get("mode", observation.get("task", observation.get("scenario", "")))
    mode = mode if isinstance(mode, str) else ""

    move = (0, 0)

    if "pursuit" in mode or "evasion" in mode:
        enemy = nearest_delta(pos, targets)
        if enemy is not None:
            move = (-sign(enemy[0]), -sign(enemy[1]))
            # prefer axis that increases distance and is legal
            cand = []
            if abs(enemy[0]) >= abs(enemy[1]):
                cand = [(-sign(enemy[0]), 0), (0, -sign(enemy[1]))]
            else:
                cand = [(0, -sign(enemy[1])), (-sign(enemy[0]), 0)]
            cand.append(move)
            for c in cand:
                if c in options:
                    move = c
                    break
        else:
            move = options[0]

    elif "territory" in mode or "control" in mode:
        # move toward nearest target if any, otherwise explore with slight bias
        tgt = nearest_delta(pos, targets)
        if tgt is not None:
            pref = (sign(tgt[0]), sign(tgt[1]))
            candidates = []
            if abs(tgt[0]) > abs(tgt[1]):
                candidates = [(sign(tgt[0]), 0), (0, sign(tgt[1])), pref]
            else:
                candidates = [(0, sign(tgt[1])), (sign(tgt[0]), 0), pref]
            for c in candidates:
                if c in options:
                    move = c
                    break
        else:
            move = options[(pos[0] + 2 * pos[1]) % len(options)]

    else:
        # resource_collection or unknown: go to nearest resource/target; else explore
        tgt = nearest_delta(pos, targets)
        if tgt is not None:
            pref = (sign(tgt[0]), sign(tgt[1]))
            candidates = []
            if abs(tgt[0]) >= abs(tgt[1]):
                candidates = [(sign(tgt[0]), 0), (0, sign(tgt[1])), pref]
            else:
                candidates = [(0, sign(tgt[1])), (sign(tgt[0]), 0), pref]
            for c in candidates:
                if c in options:
                    move = c
                    break
        else:
            # mild exploration preference
            idx = (pos[0] * 31 + pos[1] * 17 + len(options)) % len(options)
            move = options[idx]

    move = choose_from_options(options, move)
    return [clamp1(move[0]), clamp1(move[1])]

